import string

def encode_cyclic(s: str):
    """
    returns encoded string by cycling groups of three characters.
    """
    # split string to groups. Each of length 3.
    groups = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    # cycle elements in each group. Unless group has fewer elements than 3.
    groups = [(group[1:] + group[0]) if len(group) == 3 else group for group in groups]
    return "".join(groups)


def decode_cyclic(s: str):
    """
    takes as input string encoded with encode_cyclic function. Returns decoded string.
    """
    def cycle_left(s: str):
        return s[-1] + s[:-1]

    def decode_group(group: str):
        if len(group) == 1:
            return group
        else:
            next_group = cycle_left(group)
            if all(next_group == group) and len(group) > 1:
                # Repeated group with length more than 1, indicating a cycle of length 3.
                return cycle_left(cycle_left(group))
            elif len(group) == 1:
                return group
            else:
                # Simple group with possible offset.
                return group[:-1] + group[-1]

    # split encoded string to individual groups, then decode each group.
    return "".join(decode_group(group) for group in s)

