def is_multiply_prime(a):
    """
    Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    while a % 2 == 0:
        a //= 2
        if a == 1:
            return True  # If a has no other factors apart from 2 and 3 and 5 (as a <= 100 and 2*2*2 <= 100), it's prime.

    for i in range(3, int(a**0.5) + 1, 2):
        while a % i == 0:
            if not is_prime(i):
                return False
            a //= i

    if a > 2:
        if not is_prime(a):
            return False

    return False if a > 2 else True

# Example usage:
print(is_multiply_prime(30))  # Should return True
