def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    # Convert strings to floats if they contain a float (checking for '.' or ',')
    try:
        float_a = float(str(a).replace(',', '.'))
    except:
        float_a = a

    try:
        float_b = float(str(b).replace(',', '.'))
    except:
        float_b = b

    # Return None if the float values are equal
    if float_a == float_b:
        return None

    # Return the larger value in its original type
    if isinstance(float_a, float) and float(float_a) > float(float_b):
        return float_b if isinstance(float_b, str) else float_a
    else:
        return a if isinstance(a, str) else b
